const clone=value=>structuredClone(value??{}),escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const lists={transaction:'transactions',transfer:'transfers',account:'accounts',payment:'payments',debt:'debts',goal:'goals',budget:'budgets'};
const labels={transaction:'Операция',transfer:'Перевод',account:'Счёт',payment:'Платёж',debt:'Долг',goal:'Цель',budget:'Лимит'};
const tabs=[['overview','Обзор'],['transactions','Операции'],['payments','Платежи'],['debts','Долги']];
const categories=['Продукты','Кафе и рестораны','Транспорт','Жильё','Связь и интернет','Подписки','Здоровье','Развлечения','Путешествия','Дом и быт','Подарки','Одежда','Образование','Переводы','Кредиты','Прочее'];
const money=(amount,currency='RUB')=>`${Number(amount||0).toLocaleString('ru-RU',{maximumFractionDigits:2})} ${{RUB:'₽',USD:'$',EUR:'€'}[currency]||currency}`;
const rate=(finance,currency)=>currency==='RUB'?1:Number(finance.rates?.[currency])>0?Number(finance.rates[currency]):null;
const shortDate=value=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(value||'')))return String(value||'');return new Date(value+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});};
const round=value=>Math.round((Number(value)+Number.EPSILON)*100)/100;
const required=(condition,message)=>{if(!condition)throw new Error(message)};
const balance=(finance,account)=>Number(account.opening||0)+(finance.transactions||[]).filter(row=>row.accountId===account.id).reduce((sum,row)=>sum+(row.kind==='income'?1:-1)*Number(row.amount||0),0)+(finance.transfers||[]).reduce((sum,row)=>sum+(row.toId===account.id?Number(row.toAmount||0):0)-(row.fromId===account.id?Number(row.amount||0):0),0);
export function projectFinance(model){
 const finance=model.finance||model,today=model.today||new Date().toISOString().slice(0,10),month=today.slice(0,7),accounts=(finance.accounts||[]).map(account=>({...clone(account),balance:balance(finance,account)}));
 const monthly=(finance.transactions||[]).filter(row=>row.date?.startsWith(month)&&row.category!=='не записал');
 const sums=new Map();for(const row of monthly)if(row.kind==='expense'&&row.currency==='RUB'){const raw=String(row.category||'Прочее').trim()||'Прочее',name=raw[0].toUpperCase()+raw.slice(1);sums.set(name,(sums.get(name)||0)+Number(row.amount||0));}
 const expenses=[...sums].sort((a,b)=>b[1]-a[1]),expense=expenses.reduce((sum,[,amount])=>sum+amount,0),payments=(finance.payments||[]).map(payment=>{const fx=rate(finance,payment.currency||'RUB'),rub=fx===null?null:Number(payment.amount||0)*fx,utility=!payment.locked&&/^жил/i.test(payment.category||'');return{...clone(payment),rub,monthly:rub===null?null:utility?Math.ceil(rub/100)*100:rub/(payment.repeat==='yearly'?12:1)}});
 return{today,month,accounts,available:accounts.filter(row=>row.currency==='RUB'&&row.kind!=='goal').reduce((sum,row)=>sum+row.balance,0),foreign:accounts.filter(row=>row.currency!=='RUB'&&row.kind!=='goal'),monthly,expense,income:monthly.filter(row=>row.kind==='income'&&row.currency==='RUB').reduce((sum,row)=>sum+Number(row.amount||0),0),categories:expenses.map(([name,amount])=>({name,amount,percent:expense?amount/expense*100:0})),payments,monthlyPayments:payments.reduce((sum,row)=>sum+(row.monthly||0),0),unknownPayments:payments.filter(row=>row.monthly===null).length};
}
function nextDate(payment,today,after=false){const [y,m,d]=today.split('-').map(Number),day=Number(payment.day)||d,month=Number(payment.month)||m,pad=value=>String(value).padStart(2,'0'),at=(year,mo)=>`${year}-${pad(mo)}-${pad(Math.min(day,new Date(year,mo,0).getDate()))}`;if(payment.repeat==='yearly'){const first=at(y,month);return first>today||!after&&first===today?first:at(y+1,month);}let first=at(y,m);if(first>today||!after&&first===today)return first;return at(m===12?y+1:y,m===12?1:m+1);}
function newId(finance,entity){finance._localSequence??={};let index=Math.max(0,Number(finance._localSequence[entity])||0)+1;const ids=new Set(Object.values(finance).filter(Array.isArray).flatMap(rows=>rows.map(row=>row?.id)));while(ids.has(`local-${entity}-${index}`))index++;finance._localSequence[entity]=index;return`local-${entity}-${index}`;}
/** Pure local owner reducer. It never calls a bank, server, provider or storage. */
export function applyFinanceIntent(finance,intent,{today=new Date().toISOString().slice(0,10)}={}){
 const result=clone(finance);for(const list of Object.values(lists))result[list]??=[];
 const entity=intent.entity||'payment',list=lists[entity];required(list,'Неизвестный тип финансовой записи.');const id=intent.id??intent.record?.id,existing=result[list].find(row=>row.id===id),changes=clone(intent.changes||{}),record={...clone(existing),...clone(intent.record),...changes};
 if(intent.action==='confirm-payment'){
  const payment=result.payments.find(row=>row.id===id);required(payment,'Платёж не найден.');if(payment.status==='confirmed'||payment.paidAt===today||result.transactions.some(row=>row.paymentId===id&&row.date===today))return result;
  required(!payment.locked,'Платёж связан с кредитом. Подтверди его через владельца кредита.');const horizon=new Date(today+'T12:00:00');horizon.setDate(horizon.getDate()+14);required(!payment.nextOn||payment.nextOn<=horizon.toISOString().slice(0,10),'Следующий срок платежа дальше двух недель. Этот период здесь не списывается повторно.');const currency=payment.currency||'RUB';
  const account=payment.accountId?result.accounts.find(row=>row.id===payment.accountId):result.accounts.find(row=>row.currency===currency&&row.kind!=='goal'&&!row.archived&&/(постоянн|обязательн|на расход|на сч[её]та|коммунал)/i.test(row.name||''))||result.accounts.find(row=>row.currency===currency&&row.kind!=='goal'&&!row.archived&&row.isDefault)||result.accounts.find(row=>row.currency===currency&&row.kind!=='goal'&&!row.archived);
  required(account,`Нет счёта в ${currency}. Выбери счёт для платежа.`);required(account.currency===currency,'Платёж и счёт в разных валютах. Нужна сумма фактического списания; конвертация не придумана.');required(Number(payment.amount)>0,'Укажи положительную сумму платежа.');
  result.transactions.push({id:newId(result,'transaction'),title:payment.title,kind:'expense',amount:Number(payment.amount),currency,category:payment.category||'Прочее',accountId:account.id,date:today,project:'Финансы',manual:true,paymentId:id});payment.status='confirmed';payment.paidAt=today;payment.lastAmount=Number(payment.amount);payment.lastPaidOn=payment.nextOn||today;
  if(payment.nextOn&&today<payment.nextOn&&payment.repeat!=='yearly'){payment.day=Number(today.slice(8));payment.lastPaidOn=today;}payment.nextOn=nextDate(payment,payment.lastPaidOn,true);return result;
 }
 if(intent.action==='delete'){
  if(entity==='payment')required(!existing?.locked,'Платёж управляется кредитом и здесь не удаляется.');
  required(existing,'Запись не найдена.');if(entity==='account'){const permanent=result.accounts.find(row=>row.savings)||result.accounts.find(row=>row.kind==='deposit');required(existing!==permanent,'Основной накопительный счёт нельзя удалить.');required(!result.transactions.some(row=>row.accountId===id)&&!result.transfers.some(row=>row.fromId===id||row.toId===id)&&!result.goals.some(row=>row.accountId===id)&&!result.payments.some(row=>row.accountId===id),'Сначала перенеси связанные операции и записи на другой счёт.');}result[list]=result[list].filter(row=>row.id!==id);return result;
 }
 if(entity==='payment')required(!existing?.locked,'Платёж управляется кредитом и здесь не редактируется.');
 required(['create','update'].includes(intent.action),'Действие требует отдельного владельца и пока не выполнено.');if(intent.action==='update')required(existing,'Редактируемая запись не найдена.');if(intent.action==='create')required(!existing,'Запись с таким идентификатором уже есть.');record.id=id||newId(result,entity);
 const positive=(key,label)=>required(Number.isFinite(Number(record[key]))&&Number(record[key])>0,`${label} должна быть больше нуля.`),nonnegative=(key,label)=>required(Number.isFinite(Number(record[key]||0))&&Number(record[key]||0)>=0,`${label} не может быть отрицательной.`),named=(key='title')=>required(String(record[key]||'').trim(),'Укажи название.');
 if(entity==='transaction'){named();positive('amount','Сумма');required(['income','expense'].includes(record.kind),'Выбери доход или расход.');const account=result.accounts.find(row=>row.id===record.accountId&&row.kind!=='goal');required(account,'Выбери существующий счёт.');record.currency=account.currency;record.date||=today;record.manual=true;}
 if(entity==='transfer'){positive('amount','Сумма списания');positive('toAmount','Сумма зачисления');const from=result.accounts.find(row=>row.id===record.fromId),to=result.accounts.find(row=>row.id===record.toId);required(from&&to&&from.id!==to.id,'Выбери два разных существующих счёта.');required(from.currency!==to.currency||Number(record.amount)===Number(record.toAmount),'Для одной валюты суммы списания и зачисления должны совпадать.');record.date||=today;}
 if(entity==='account'){named('name');required(String(record.currency||''),'Укажи валюту.');const linked=existing&&(result.transactions.some(row=>row.accountId===id)||result.transfers.some(row=>row.fromId===id||row.toId===id));required(!linked||existing.currency===record.currency,'Валюту счёта со связанными операциями менять нельзя.');record.kind||='card';const desired=Number(record.balanceNow??(existing?balance(result,existing):record.opening??record.balance??0));required(Number.isFinite(desired),'Проверь остаток счёта.');if(existing){const delta=round(desired-balance(result,existing));if(Math.abs(delta)>=.01)result.transactions.push({id:newId(result,'reconcile'),title:'Сверка счёта',kind:delta>0?'income':'expense',amount:Math.abs(delta),currency:record.currency,category:'не записал',accountId:id,date:today,manual:true});}else record.opening=round(desired);delete record.balanceNow;}
 if(entity==='budget'){positive('limit','Лимит');required(record.category,'Выбери категорию.');}
 if(entity==='goal'){named();positive('target','Цель');nonnegative('saved','Отложенная сумма');}
 if(entity==='payment'){named();positive('amount','Сумма');required(Number.isInteger(Number(record.day))&&Number(record.day)>=1&&Number(record.day)<=31,'Число платежа должно быть от 1 до 31.');required(!record.month||Number.isInteger(Number(record.month))&&Number(record.month)>=1&&Number(record.month)<=12,'Проверь месяц платежа.');record.currency||='RUB';record.repeat||='monthly';required(['monthly','yearly'].includes(record.repeat),'Выбери месячный или годовой повтор.');record.status||='upcoming';const changedSchedule=!existing||(existing.repeat||'monthly')!==record.repeat||Number(existing.day||String(existing.nextOn||today).slice(8))!==Number(record.day)||record.repeat==='yearly'&&Number(existing.month||String(existing.nextOn||today).slice(5,7))!==Number(record.month);if(changedSchedule)record.nextOn=nextDate(record,today);}
 if(entity==='debt'){named('person');positive('amount','Сумма');nonnegative('paid','Погашенная сумма');required(Number(record.paid||0)<=Number(record.amount),'Погашено больше общей суммы.');record.kind||='debt';if(record.kind==='credit'){nonnegative('monthly','Месячный платёж');if(record.payDay!==''&&record.payDay!==undefined)required(Number.isInteger(Number(record.payDay))&&Number(record.payDay)>=1&&Number(record.payDay)<=31,'День платежа должен быть от 1 до 31.');if(record.rate!==''&&record.rate!==undefined)required(Number(record.rate)>=0&&Number(record.rate)<=200,'Проверь процентную ставку.');}record.direction=record.kind==='credit'?'i-owe':record.direction||'to-me';required(['i-owe','to-me'].includes(record.direction),'Выбери направление долга.');}
 for(const key of ({transaction:['amount'],transfer:['amount','toAmount'],budget:['limit'],goal:['target','saved'],payment:['amount','day','month'],debt:['amount','paid','monthly','payDay','rate']}[entity]||[]))if(record[key]!==''&&record[key]!==undefined)record[key]=Number(record[key]);
 if(existing)result[list][result[list].findIndex(row=>row.id===id)]=record;else result[list].push(record);return result;
}

const field=(name,label,value,required=false)=>`<flow-field name="${name}" placeholder="${label}" aria-label="${label}" value="${escape(value)}" maxlength="500" ${required?'required':''}></flow-field>`;
const number=(name,label,value,{min=0,max,step='.01',required=false}={})=>`<label class="number"><span>${label}</span><input name="${name}" aria-label="${label}" type="number" inputmode="decimal" min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}" value="${escape(value??'')}" ${required?'required':''}></label>`;
const select=(name,label,options,value)=>{const pool=options.some(([key])=>String(key)===String(value))||!value?options:[...options,[value,value]];return `<flow-select name="${name}" aria-label="${label}" presentation="dialog" value="${escape(value)}">${pool.map(([key,title])=>`<option value="${escape(key)}">${escape(title)}</option>`).join('')}</flow-select>`;};
const date=(name,label,value)=>`<flow-date-time name="${name}" kind="date" aria-label="${label}" placeholder="${label}" value="${escape(value)}"></flow-date-time>`;
const textArea=(name,label,value)=>`<flow-text-area name="${name}" aria-label="${label}" placeholder="${label}" value="${escape(value)}" maxlength="5000"></flow-text-area>`;
