export class FlowFinanceWorkspace extends FlowControl{
 constructor(){super();this.shadowRoot.adoptedStyleSheets=[...this.shadowRoot.adoptedStyleSheets,style,overviewStyle,dialogHeaderSheet];this._model={finance:{},today:new Date().toISOString().slice(0,10),tab:'overview'};this._filter='all';this._category='';}
 get model(){return clone(this._model)}
 set model(value){this._model=clone(value);this._model.finance??={};this._model.tab||='overview';if(this.isConnected)this.render();}
 get draft(){const form=this.shadowRoot.querySelector('form');if(!form)return null;const values=new FormData(form),record=clone(this._editing?.record);for(const[key,value]of values){record[key]=form.querySelector(`input[type=number][name="${CSS.escape(key)}"]`)?value===''?'':Number(value):String(value).trim();}if(this._editing.entity==='account'){record.balanceNow=Number(record.balanceNow||0);}return record;}
 get dirty(){return !!this._baseline&&JSON.stringify(this.draft)!==this._baseline}
 feedbackTarget(event){return this.shadowRoot.querySelector('dialog[open]')||event?.composedPath().find(node=>node instanceof Element&&node.matches('.card,.flow-summary,.debt-context'))||this.shadowRoot.querySelector('.card,.workspace')}
 connectedCallback(){if(!this.shadowRoot.firstChild)this.render()}
 emitIntent(action,entity,id,record,changes={}){return this.dispatchEvent(new CustomEvent('flow-finance-intent',{detail:{action,entity,id,record:clone(record),changes:clone(changes),context:{today:this._model.today,tab:this._model.tab,dirty:this.dirty}},bubbles:true,composed:true,cancelable:true}));}
 setTab(tab,{keepCategory=false}={}){if(tab==='transactions'&&!keepCategory)this._category='';this._model.tab=tab;const primary=['accounts','goals','budgets'].includes(tab)?'overview':tab==='transfers'?'transactions':tab;this.shadowRoot.querySelector('flow-tabs').value=primary;for(const button of this.shadowRoot.querySelectorAll('[data-tab]')){if(button.dataset.tab===tab)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}this.renderContent();this.emit('flow-finance-tab',{tab});}
 acceptSaved(value){this.closeForm();this._model=clone(value?.finance?value:{...this._model,finance:value});this.render();}
 error(message){const status=this.shadowRoot.querySelector('dialog[open] .status')||this.shadowRoot.querySelector('[data-screen-status]');if(status)status.textContent=message;}
 render(){this.shadowRoot.innerHTML=`<section class="workspace"><flow-tabs aria-label="Разделы финансов" value="${escape(['accounts','goals','budgets','transfers'].includes(this._model.tab)?this._model.tab==='transfers'?'transactions':'overview':this._model.tab)}">${tabs.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</flow-tabs><nav class="views" aria-label="Другие разделы финансов">${[['accounts','Счета'],['goals','Цели'],['budgets','Лимиты'],['transfers','Переводы']].map(([key,label])=>`<button type="button" data-tab="${key}" ${this._model.tab===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div data-content></div><p class="status" data-screen-status role="status"></p><dialog></dialog></section>`;this.shadowRoot.querySelector('flow-tabs').addEventListener('change',event=>this.setTab(event.target.value));for(const button of this.shadowRoot.querySelectorAll('[data-tab]'))button.onclick=()=>this.setTab(button.dataset.tab);this.renderContent();}
 renderContent(){const finance=this._model.finance,p=projectFinance(this._model),tab=this._model.tab,content=this.shadowRoot.querySelector('[data-content]');if(!content)return;const add=(entity,kind='')=>`<flow-button variant="icon" icon="plus" label="Добавить: ${labels[entity]}" data-create="${entity}" data-kind="${kind}"></flow-button>`,header=(title,entity)=>`<header class="header"><h3>${title}</h3>${add(entity)}</header>`,row=(entity,item,title,meta,amount,currency='RUB')=>`<button type="button" class="row" data-open="${entity}" data-id="${escape(item.id)}"><span class="copy"><strong>${escape(title)}</strong><small>${escape(meta||'')}</small></span><span class="amount ${item.kind==='income'?'income':''}">${amount===undefined?'':money(amount,currency)}</span></button>`;
 const accountRows=()=>p.accounts.map(account=>row('account',account,account.name,account.kind==='goal'?'Цель':account.currency,account.balance,account.currency)).join('');
 if(tab==='overview')content.innerHTML=this.overviewMarkup(finance,p);
 if(tab==='accounts')content.innerHTML=`<section class="card">${header('Счета','account')}${accountRows()||'<p class="empty">Счетов пока нет.</p>'}</section>`;
 if(tab==='transactions'){const all=finance.transactions||[],filtered=all.filter(item=>(this._filter==='all'||item.kind===this._filter)&&(!this._category||String(item.category||'').toLocaleLowerCase('ru')===this._category.toLocaleLowerCase('ru'))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));content.innerHTML=`<section class="card">${header(this._category||'Операции','transaction')}${select('transactionFilter','Вид операции',[['all','Все операции'],['expense','Расходы'],['income','Доходы']],this._filter)}${filtered.map(item=>row('transaction',item,item.title,`${item.date||''} · ${item.category||''} · ${finance.accounts?.find(a=>a.id===item.accountId)?.name||''}`,`${item.kind==='income'?1:-1}`*Number(item.amount),item.currency||'RUB')).join('')||'<p class="empty">Операций пока нет.</p>'}</section>`;content.querySelector('[name=transactionFilter]').addEventListener('input',event=>{this._filter=event.target.value;if(this._filter==='all')this._category='';this.renderContent()});}
 if(tab==='payments')content.innerHTML=`<section class="card facts"><div><small class="muted">Обязательные платежи в месяц</small><strong>${money(p.monthlyPayments)}</strong>${p.unknownPayments?`<small class="muted">Ещё ${p.unknownPayments}: нет курса валюты</small>`:''}</div></section><section class="card">${header('Платежи','payment')}${p.payments.map(item=>`<article class="payment"><button class="copy" type="button" data-open="payment" data-id="${escape(item.id)}"><strong>${escape(item.title)}</strong><small>${escape(item.nextOn?shortDate(item.nextOn):`${item.day}-го`)} · ${escape(item.category||'')}${item.repeat==='yearly'?' · ежегодно':''}</small></button><span class="amount">${money(item.amount,item.currency||'RUB')}</span><flow-button label="${item.status==='confirmed'?'Оплачено':'Списалось'}" data-confirm="${escape(item.id)}" ${item.status==='confirmed'?'disabled':''}></flow-button></article>`).join('')||'<p class="empty">Платежей пока нет.</p>'}</section>`;
 if(tab==='debts'){const debts=finance.debts||[],sum=direction=>debts.filter(item=>item.direction===direction&&item.kind!=='credit').reduce((total,item)=>total+Math.max(0,Number(item.amount)-Number(item.paid||0)),0);content.innerHTML=`<section class="card facts"><div><small class="muted">Должны мне</small><strong>${money(sum('to-me'))}</strong></div><div><small class="muted">Должен я</small><strong>${money(sum('i-owe'))}</strong></div></section><section class="card">${header('Долги и кредиты','debt')}${debts.map(item=>row('debt',item,item.person,`${item.kind==='credit'?'Кредит':item.direction==='to-me'?'Должны мне':'Должен я'}${item.note?` · ${item.note}`:''}`,Math.max(0,Number(item.amount)-Number(item.paid||0)),item.currency||'RUB')).join('')||'<p class="empty">Долгов пока нет.</p>'}<flow-actions><flow-button label="Добавить кредит" data-create="debt" data-kind="credit"></flow-button></flow-actions></section>`;}
 if(tab==='goals')content.innerHTML=`<section class="card">${header('Цели','goal')}${(finance.goals||[]).map(item=>`<div class="category">${row('goal',item,item.title,item.note,Number(item.saved||0))}<small class="muted">из ${money(item.target)}</small><div class="track"><i style="width:${Math.min(100,Number(item.saved||0)/Math.max(1,Number(item.target))*100)}%"></i></div></div>`).join('')||'<p class="empty">Целей пока нет.</p>'}</section>`;
 if(tab==='budgets')content.innerHTML=`<section class="card">${header('Лимиты','budget')}${(finance.budgets||[]).map(item=>{const spent=p.monthly.filter(row=>row.kind==='expense'&&row.currency==='RUB'&&row.category===item.category).reduce((sum,row)=>sum+Number(row.amount),0);return`<div class="category">${row('budget',item,item.category,`Потрачено ${money(spent)}`,item.limit)}<div class="track"><i style="width:${Math.min(100,spent/Math.max(1,item.limit)*100)}%"></i></div></div>`}).join('')||'<p class="empty">Лимитов пока нет.</p>'}</section>`;
 if(tab==='transfers')content.innerHTML=`<section class="card">${header('Переводы','transfer')}${(finance.transfers||[]).map(item=>{const from=finance.accounts?.find(a=>a.id===item.fromId),to=finance.accounts?.find(a=>a.id===item.toId);return row('transfer',item,`${from?.name||'Счёт'} → ${to?.name||'Счёт'}`,`${item.date||''} · зачислено ${money(item.toAmount,to?.currency||'RUB')}`,item.amount,from?.currency||'RUB')}).join('')||'<p class="empty">Переводов пока нет.</p>'}</section>`;
 for(const button of content.querySelectorAll('[data-overview-tab]'))button.onclick=()=>this.setTab(button.dataset.overviewTab);for(const button of content.querySelectorAll('[data-overview-kind]'))button.onclick=()=>{this._category='';this._filter=button.dataset.overviewKind;this.setTab('transactions',{keepCategory:true});};
 for(const button of content.querySelectorAll('[data-create]'))button.onclick=()=>this.openForm(button.dataset.create,null,button.dataset.kind);for(const button of content.querySelectorAll('[data-open]'))button.onclick=()=>this.openForm(button.dataset.open,button.dataset.id);for(const button of content.querySelectorAll('[data-confirm]'))button.onclick=()=>{const record=finance.payments?.find(item=>String(item.id)===button.dataset.confirm);this.emitIntent('confirm-payment','payment',record?.id,record,{date:this._model.today});};for(const button of content.querySelectorAll('[data-category]'))button.onclick=()=>{this._category=button.dataset.category;this._filter='expense';this.setTab('transactions',{keepCategory:true});};
 }
 /** Native overview order: finance.js100–109; supplied rates only, never provider guesses. */
 overviewMarkup(finance,p){
  const validDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(String(value||''))&&new Date(value+'T12:00:00').toLocaleDateString('sv-SE')===value;
  const horizon=new Date(p.today+'T12:00:00');horizon.setDate(horizon.getDate()+3);
  const limit=horizon.toLocaleDateString('sv-SE'),upcoming=p.payments.filter(item=>['pending','upcoming'].includes(item.status)&&validDate(item.nextOn)&&item.nextOn<=limit&&!item.archived).sort((a,b)=>a.nextOn.localeCompare(b.nextOn)||String(a.title).localeCompare(String(b.title),'ru'));
  const foreign=p.foreign.map(account=>{const quote=rate(finance,account.currency);return{account,rub:Number.isFinite(quote)&&Number.isFinite(account.balance)?account.balance*quote:null};}),complete=foreign.length&&foreign.every(item=>item.rub!==null),fx=foreign.reduce((sum,item)=>sum+(item.rub??0),0);
  const debtSums=direction=>{const sums=new Map();for(const item of finance.debts||[])if(item.direction===direction&&item.kind!=='credit'){const amount=Math.max(0,Number(item.amount)-Number(item.paid||0));if(Number.isFinite(amount)&&amount>0){const currency=item.currency||'RUB';sums.set(currency,(sums.get(currency)||0)+amount);}}return [...sums].map(([currency,amount])=>money(amount,currency)).join(' · ');};
  const owed=debtSums('to-me'),owe=debtSums('i-owe'),used=new Set(['USD','EUR','CNY',...p.accounts.map(item=>item.currency),...p.payments.map(item=>item.currency||'RUB')]),order=['USD','EUR','CNY'];
  const rates=Object.keys(finance.rates||{}).filter(code=>/^[A-Z]{3}$/.test(code)&&code!=='RUB'&&used.has(code)&&Number.isFinite(Number(finance.rates[code]))&&Number(finance.rates[code])>0).sort((a,b)=>(order.indexOf(a)+1||99)-(order.indexOf(b)+1||99)||a.localeCompare(b));
  const flow=(kind,label,amount)=>`<button type="button" data-overview-kind="${kind}"><span>${label}<span aria-hidden="true">${kind==='income'?'↙':'↗'}</span></span><strong>${money(amount)}</strong><small>${p.monthly.filter(item=>item.kind===kind&&item.currency==='RUB').length} оп.</small></button>`;
  const when=item=>item.nextOn===p.today?'Сегодня':item.nextOn<p.today?'Просрочен · '+shortDate(item.nextOn):shortDate(item.nextOn);
  const payment=item=>`<article class="payment" data-upcoming-payment="${escape(item.id)}"><button type="button" class="copy" data-open="payment" data-id="${escape(item.id)}"><strong>${escape(item.title)}</strong><small class="${item.nextOn<p.today?'late':''}">${escape(when(item))}${item.category?' · '+escape(item.category):''}</small></button><span class="amount">${escape(money(item.amount,item.currency||'RUB'))}</span><flow-button label="Списалось" data-confirm="${escape(item.id)}" ${item.locked?'disabled aria-label="Платёж управляется кредитом"':''}></flow-button></article>`;
  return `<div class="finance-overview"><div class="overview-main"><section class="card balance"><button type="button" class="balance-open" data-overview-tab="accounts" aria-label="Доступно в рублях, открыть счета"><small>Доступно в рублях</small><strong>${money(p.available)}</strong>${foreign.length?`<span class="foreign">Ещё ${foreign.map(({account})=>`<span title="${escape(account.name)}">${escape(money(account.balance,account.currency))}</span>`).join(' · ')}</span>`:''}${complete?`<span class="fx-total">Всего с валютой ≈ ${money(round(p.available+fx))}</span>`:''}<span class="balance-more">Все счета <span aria-hidden="true">›</span></span></button><flow-actions><flow-button variant="primary" label="Расход" icon="plus" data-create="transaction" data-kind="expense"></flow-button><flow-button label="Доход" data-create="transaction" data-kind="income"></flow-button><flow-button label="Перевод" data-create="transfer"></flow-button></flow-actions></section><section class="flow-summary" aria-label="Доходы и расходы за месяц">${flow('income','Доходы',p.income)}${flow('expense','Расходы',p.expense)}</section>${upcoming.length?`<section class="card upcoming-payments"><header class="header"><h3>Ближайшие платежи</h3><button class="text-link" type="button" data-overview-tab="payments">Все <span aria-hidden="true">›</span></button></header>${upcoming.map(payment).join('')}</section>`:''}${owed||owe?`<button type="button" class="debt-context card" data-overview-tab="debts"><span class="debt-symbol">${mapIcon('finance')}</span><span class="copy"><strong>Долги</strong><small>${escape([owed?'Мне '+owed:'',owe?'Я '+owe:''].filter(Boolean).join(' · '))}</small></span><span aria-hidden="true">›</span></button>`:''}</div><aside class="overview-aside"><section class="card category-ledger"><h3>Расходы по категориям</h3>${p.categories.length?p.categories.map(category=>`<div class="category"><button type="button" data-category="${escape(category.name)}"><strong>${escape(category.name)}</strong><small>${Math.round(category.percent)}%</small><span class="amount">${money(category.amount)}</span></button><div class="track"><i style="width:${category.percent}%"></i></div></div>`).join(''):'<p class="empty">За этот месяц расходов нет.</p>'}</section>${rates.length?`<section class="card rates-card"><h3>Курс ЦБ</h3><div class="rates-list">${rates.map(code=>`<div data-rate="${escape(code)}"><small>${escape(code)}</small><strong>${Number(finance.rates[code]).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:Number(finance.rates[code])<1?4:2})} ₽</strong></div>`).join('')}</div></section>`:''}</aside></div>`;
 }
 openForm(entity,idOrRecord=null,kind=''){
  const finance=this._model.finance,original=typeof idOrRecord==='object'?idOrRecord:(finance[lists[entity]]||[]).find(item=>String(item.id)===String(idOrRecord));if(!lists[entity])return;if(entity==='payment'&&original?.locked){this.error('Этот платёж управляется кредитом. Открой кредит в разделе долгов.');return;}this._editing={entity,record:clone(original),kind};const record=clone(original),v=key=>record[key]??'',accounts=(finance.accounts||[]).filter(item=>item.kind!=='goal').map(item=>[item.id,`${item.name} · ${item.currency}`]),currencies=[...new Set(['RUB','USD','EUR',...Object.keys(finance.rates||{}),...(finance.accounts||[]).map(item=>item.currency)])].map(value=>[value,value]),cats=[...new Set([...categories,...(finance.transactions||[]).map(item=>item.category),record.category].filter(Boolean))].map(value=>[value,value]),today=this._model.today;let fields='';
  if(entity==='transaction')fields=`${field('title','Название',v('title'),true)}${number('amount','Сумма',v('amount'),{min:.01,required:true})}<div class="pair">${select('kind','Тип операции',[['expense','Расход'],['income','Доход']],v('kind')||kind||'expense')}${select('accountId','Счёт',accounts,v('accountId')||accounts[0]?.[0]||'')}</div><div class="pair">${date('date','Дата',v('date')||today)}${select('category','Категория',cats,v('category')||'Прочее')}</div>${field('project','Проект',v('project'))}`;
  if(entity==='account')fields=`${field('name','Название счёта',v('name'),true)}${select('currency','Валюта',currencies,v('currency')||'RUB')}${number('balanceNow','Остаток сейчас',original?balance(finance,original):v('opening')||0,{min:-100000000,required:true})}`;
  if(entity==='transfer')fields=`<div class="pair">${select('fromId','Со счёта',accounts,v('fromId')||accounts[0]?.[0]||'')}${select('toId','На счёт',accounts,v('toId')||accounts[1]?.[0]||'')}</div><div class="pair">${number('amount','Списать',v('amount'),{min:.01,required:true})}${number('toAmount','Зачислить',v('toAmount'),{min:.01,required:true})}</div>${date('date','Дата',v('date')||today)}${textArea('note','Комментарий',v('note'))}`;
  if(entity==='payment')fields=`${field('title','Название платежа',v('title'),true)}<div class="pair">${number('amount','Сумма',v('amount'),{min:.01,required:true})}${select('currency','Валюта',currencies,v('currency')||'RUB')}</div><div class="pair">${select('repeat','Повтор',[['monthly','Каждый месяц'],['yearly','Каждый год']],v('repeat')||'monthly')}${number('day','Число',v('day')||Number(today.slice(8)),{min:1,max:31,step:1,required:true})}</div><div data-payment-month>${select('month','Месяц',Array.from({length:12},(_,i)=>[i+1,new Date(2026,i,1).toLocaleDateString('ru',{month:'long'})]),v('month')||Number(today.slice(5,7)))}</div>${select('category','Категория',cats,v('category')||'Подписки')}${select('accountId','Счёт для списания',[['','Автоматически по валюте'],...accounts],v('accountId'))}${date('endsOn','Последний платёж',v('endsOn'))}`;
  if(entity==='debt'){const credit=record.kind==='credit'||kind==='credit';fields=`${field('person',credit?'Кредит или банк':'Человек',v('person'),true)}<input type="hidden" name="kind" value="${credit?'credit':'debt'}">${credit?'<input type="hidden" name="direction" value="i-owe">':select('direction','Направление',[['to-me','Должны мне'],['i-owe','Должен я']],v('direction')||'to-me')}<div class="pair">${number('amount','Всего',v('amount'),{min:.01,required:true})}${number('paid','Уже погашено',v('paid')||0)}</div>${credit?`${number('monthly','Платёж в месяц',v('monthly'))}<div class="pair">${number('payDay','День платежа',v('payDay'),{min:1,max:31,step:1})}${number('rate','Ставка, %',v('rate'),{max:200})}</div>${date('endsOn','Последний платёж',v('endsOn'))}`:''}${textArea('note','За что',v('note'))}`;}
  if(entity==='goal')fields=`${field('title','Название цели',v('title'),true)}<div class="pair">${number('target','Нужно накопить',v('target'),{min:.01,required:true})}${number('saved','Уже отложено',v('saved')||0)}</div>${textArea('note','Пояснение',v('note'))}`;
  if(entity==='budget')fields=`${select('category','Категория',cats,v('category')||cats[0]?.[0]||'Прочее')}${number('limit','Лимит в месяц',v('limit'),{min:.01,required:true})}`;
  const dialog=this.shadowRoot.querySelector('dialog');dialog.innerHTML=`<form>${dialogHeader(`${original?'Изменить':'Добавить'} ${{transaction:'операцию',transfer:'перевод',account:'счёт',payment:'платёж',debt:record.kind==='credit'||kind==='credit'?'кредит':'долг',goal:'цель',budget:'лимит'}[entity]}`,'finance-form-title')}<div class="form-body fields">${fields}<p class="status" role="alert"></p></div><footer><flow-actions>${original?'<flow-button stretch variant="danger" icon="trash" label="Удалить" data-delete></flow-button>':''}<flow-button stretch variant="primary" label="Сохранить" data-save></flow-button></flow-actions></footer></form>`;const form=dialog.querySelector('form');if(entity==='payment'){const syncMonth=()=>form.querySelector('[data-payment-month]').hidden=form.querySelector('[name=repeat]').value!=='yearly';form.querySelector('[name=repeat]').addEventListener('input',syncMonth);syncMonth();}this._baseline=JSON.stringify(this.draft);const save=()=>{if(form.reportValidity())this.emitIntent(original?'update':'create',entity,record.id,this.draft)};form.onsubmit=event=>{event.preventDefault();save()};dialog.querySelector('[data-save]').onclick=save;dialog.querySelector('[data-delete]')?.addEventListener('click',()=>this.emitIntent('delete',entity,record.id,this.draft));dialog.querySelector('.dialog-close').onclick=()=>this.emitIntent('close-form',entity,record.id,this.draft);dialog.oncancel=event=>{event.preventDefault();this.emitIntent('close-form',entity,record.id,this.draft)};dialog.showModal();this.emitIntent('open',entity,record.id,record);
 }
 closeForm(){const dialog=this.shadowRoot.querySelector('dialog');if(dialog?.open)dialog.close();if(dialog)dialog.replaceChildren();this._editing=null;this._baseline=null;}
 disconnectedCallback(){this.closeForm();super.disconnectedCallback()}
}
if(!customElements.get('flow-finance-workspace'))customElements.define('flow-finance-workspace',FlowFinanceWorkspace);
